import {VERSION,ELEMENTS,MOVES,SPECIES,STARTERS,ITEMS,RECIPES,STATUS,WEATHER,CHAPTERS,SIDEQUESTS,ENDING} from './data.js';
import {clamp,clone,random,stats,moveList,createMon,createGame,healParty,makeBattle,takeTurn,settleBattle,questReady,saveEnvelope,readEnvelope,xpNeed,effectiveness,completeStory} from './engine.js';
import {makeMap,TILE,drawWorld,nearest,canWalk,camera,tileKind} from './world.js';
import {drawMonster,drawPerson,drawProp} from './art.js';
import {SIDE_STORIES,CAMPFIRE_TALKS} from './stories.js';
import {FrameMetrics,easePosition} from './performance.js';
import {drawTitleVista} from './landmarks.js';
import {drawBattleScene} from './battle-view.js';
import {turnRune,gateIsOpen,runeValue,RUNE_SYMBOLS} from './dungeon-engine.js';

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const canvas=$('#world'),ctx=canvas.getContext('2d');
const SAVE='starfall-save-v1',BACKUP='starfall-save-backup-v1';
let game=null,map=null,fight=null,dialogue=null,modalType='',modalLastFocus=null,frameTime=0,lastFrame=0,moveCooldown=0,walkingUntil=0,toastTimer,zoneTimer,lastInteraction='',heldKeys=new Set(),pathQueue=[],lastStepCount=0,battleMenu='root',soundContext=null,musicTimer=null,musicStep=0,lastSaveTick=0;
let view={w:1200,h:760,dpr:1};
const metrics=new FrameMetrics();let visualPlayer={x:18,y:19},lastMetricsUpdate=0,battleEffect=null,pendingBattle=null,renderDirty=true;
const titleGame={region:0,place:'town',x:21,y:16,party:[],collected:{},facing:'down'},titleMap=makeMap(0,'town');
let savedText=null;
try{savedText=localStorage.getItem(SAVE)||localStorage.getItem(BACKUP);if(savedText)readEnvelope(savedText);}catch(e){try{savedText=localStorage.getItem(BACKUP);if(savedText)readEnvelope(savedText);}catch{savedText=null;}}
if(savedText)$('#continue-button').classList.remove('hidden');
const typeTag=id=>`<span class="type-tag" style="color:${ELEMENTS[id].color}">${ELEMENTS[id].name}属性</span>`;
const monCanvas=(id,size=120)=>`<canvas width="${size*2}" height="${size*2}" style="width:${size}px;height:${size}px" data-species="${id}"></canvas>`;
function paintMonCanvases(){for(const c of $$('canvas[data-species]')){const cc=c.getContext('2d');cc.clearRect(0,0,c.width,c.height);drawMonster(cc,SPECIES[c.dataset.species],0,0,c.width,{time:frameTime});}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),3800);}
function resize(){const r=$('#stage').getBoundingClientRect();view={w:r.width,h:r.height,dpr:Math.min(devicePixelRatio||1,game?.quality==='performance'?1:game?.quality==='balanced'?1.5:2)};canvas.width=Math.round(view.w*view.dpr);canvas.height=Math.round(view.h*view.dpr);ctx.setTransform(view.dpr,0,0,view.dpr,0,0);ctx.imageSmoothingEnabled=false;renderDirty=true;}
new ResizeObserver(resize).observe($('#stage'));

function save(notify=false){if(!game)return;try{game.lastSave=Date.now();const previous=localStorage.getItem(SAVE);if(previous)localStorage.setItem(BACKUP,previous);localStorage.setItem(SAVE,saveEnvelope(game));$('#save-indicator').textContent='已保存 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});if(notify)toast('旅途已保存。');}catch{toast('浏览器存储空间不足，请在设置中导出存档。');}}
function startGame(g){game=g;visualPlayer={x:game.x,y:game.y};resize();metrics.reset();map=makeMap(game.region,game.place,game.dungeonFloor||0);if(!canWalk(map,game,game.x,game.y)&&map.entry){game.x=map.entry.x;game.y=map.entry.y;visualPlayer={x:game.x,y:game.y};}fight=null;pendingBattle=null;battleEffect=null;dialogue=null;$('#dialogue').classList.add('hidden');heldKeys.clear();pathQueue=[];$('#title-screen').classList.add('hidden');$('#world-ui').classList.remove('hidden');$('#game-nav').classList.remove('hidden');$('#mobile-controls').classList.remove('hidden');$('#battle-screen').classList.add('hidden');$('#sound-button').textContent=game.sound?'♫':'♩';updateHUD();canvas.focus();announceZone();if(game.sound)startMusic();}
function announceZone(){const c=CHAPTERS[game.region];$('#zone-toast').innerHTML=escape(map.floorName||c[game.place])+`<small>${escape(c.island)} · ${escape(c.name)}</small>`;$('#zone-toast').classList.remove('hidden');clearTimeout(zoneTimer);zoneTimer=setTimeout(()=>$('#zone-toast').classList.add('hidden'),2600);}
function updateHUD(){if(!game)return;const ch=CHAPTERS[game.region];$('#chapter-label').textContent=`第 ${game.region+1} 章 · ${ch.name}`;$('#place-name').textContent=map.floorName||ch[game.place];$('#weather-label').textContent=WEATHER[ch.weather].icon+' '+WEATHER[ch.weather].name;$('#region-label').textContent=ch.island;$('#gold-label').textContent=game.gold.toLocaleString();$('#badge-label').textContent=`✧ ${game.badges.length} / 8`;
 const fragments=fragmentCount();$('#quest-pin').innerHTML=game.badges.includes(game.region)?`<b>✦ ${escape(ch.reward)}已点亮</b>${game.region<7?'前往港口，与航海人对话，启程去下一座岛。':'星潮已经退去。还可以完成委托，探索图鉴，挑战守灯人。'}`:`<b>✦ ${escape(ch.name)}</b>${escape(ch.task)}<br><span style="color:var(--gold)">已收集 ${fragments} / 3</span>`;
 if(game.place==='dungeon'&&!game.badges.includes(game.region))$('#quest-pin').innerHTML=`<b>✦ ${escape(ch.dungeon)} · 第 ${(game.dungeonFloor||0)+1} / 4 层</b>${game.dungeonFloor===3?'寻找守灯人，回应这座岛的记忆。':'阅读石碑线索，调整日、月、星符柱，打开通往下一层的封门。'}`;
 $('#party-dock').innerHTML=game.party.map((m,i)=>`<button class="mini-mon" data-mon="${i}" aria-label="${escape(SPECIES[m.species].name)}，${m.level}级，生命${m.hp}"><span class="mini-level">${m.level}</span><canvas width="104" height="96" data-species="${m.species}"></canvas><div class="mini-hp"><i style="width:${m.hp/stats(m).hp*100}%;background:${m.hp===0?'#b57474':'#83c9b9'}"></i></div></button>`).join('');paintMonCanvases();$$('[data-mon]').forEach(el=>el.onclick=()=>openMon(game.party[+el.dataset.mon]));}
function fragmentCount(){return [0,1,2].filter(i=>game.flags[`fragment${game.region}-${i}`]).length;}

function openModal(title,html,type='generic',eyebrow='旅途的一部分'){
 heldKeys.clear();pathQueue=[];if($('#modal').classList.contains('hidden'))modalLastFocus=document.activeElement;modalType=type;$('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-content').innerHTML=html;$('#modal').classList.remove('hidden');$('#modal-close').focus();paintMonCanvases();}
function closeModal(){metrics.reset();renderDirty=true;if(modalType==='starter'&&!game){$('#modal').classList.add('hidden');modalType='';return;}$('#modal').classList.add('hidden');modalType='';if(modalLastFocus?.isConnected)modalLastFocus.focus();else canvas.focus();}
$('#modal-close').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal();};
function beginNew(){openModal('选择与你同行的潮灵',`<p class="section-note">故事开始于一个名字，和一次愿意同行的约定。三位伙伴拥有不同的属性，旅途中还会遇到更多潮灵。</p><label class="eyebrow" for="traveler-name">你希望大家怎样称呼你？</label><input id="traveler-name" class="name-input" maxlength="12" placeholder="旅人" value="旅人"><div class="grid starter-grid">${STARTERS.map(id=>`<button class="card starter-card" data-starter="${id}">${monCanvas(id,140)}${typeTag(SPECIES[id].element)}<h3>${SPECIES[id].name}</h3><p>${SPECIES[id].lore}</p><div class="move-chip">${id==='budfox'?'恢复与牵制':id==='embercat'?'爆发与灼伤':'耐久与控场'}</div></button>`).join('')}</div>`,'starter','第一份约定');$$('[data-starter]').forEach(b=>b.onclick=()=>{const g=createGame($('#traveler-name').value,b.dataset.starter);g.flags['entered0']=true;closeModal();startGame(g);save();showDialogue(CHAPTERS[0].intro,()=>toast('使用 WASD / 方向键移动。靠近人物或发光物体，按 E 互动。'));});}
$('#new-button').onclick=()=>{if(savedText)openModal('开始新的旅程',`<p class="section-note">新的旅途会覆盖浏览器中的当前存档。可以先导出旧存档，随时再回来。</p><div class="card-actions"><button id="backup-start">导出旧存档</button><button id="confirm-start">开始新旅程</button></div>`,'new-confirm');else return beginNew();$('#backup-start').onclick=()=>downloadSave(savedText);$('#confirm-start').onclick=beginNew;};
$('#continue-button').onclick=()=>{try{startGame(readEnvelope(savedText));toast('欢迎回来，'+game.name+'。');}catch(e){toast('读取失败：'+e.message);}};
function downloadSave(text=saveEnvelope(game)){if(!text)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download='星潮纪行-旅途存档-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
$('#import-title').onclick=()=>$('#save-file').click();$('#save-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw new Error('存档文件过大。');const imported=readEnvelope(await f.text());if(game){openModal('载入这段旅程？',`<p class="section-note">将载入 ${escape(imported.name)} 的旅程：${CHAPTERS[imported.region].island}，${imported.badges.length} 枚灯印。当前存档会自动保留一份备份。</p><button class="primary" id="confirm-import">载入存档</button>`);$('#confirm-import').onclick=()=>{save();closeModal();startGame(imported);save();};}else{startGame(imported);save();}}catch(err){toast('存档无法读取：'+err.message);}e.target.value='';};

function showDialogue(lines,done){dialogue={lines,index:0,done};heldKeys.clear();pathQueue=[];$('#dialogue').classList.remove('hidden');renderDialogue();}
function renderDialogue(){const [speaker,text]=dialogue.lines[dialogue.index];$('#speaker').textContent=speaker==='旅人'?game.name:speaker;$('#dialogue-text').textContent=text;const pc=$('#portrait-canvas'),cx=pc.getContext('2d');cx.clearRect(0,0,96,96);drawPerson(cx,0,0,96,{role:speaker==='阿汐'?'rival':speaker.includes('博士')?'scholar':speaker==='旅人'?'player':'warden',time:frameTime});$('#dialogue-next').focus();sfx('talk');}
function nextDialogue(){if(!dialogue)return;dialogue.index++;if(dialogue.index>=dialogue.lines.length){const done=dialogue.done;dialogue=null;$('#dialogue').classList.add('hidden');canvas.focus();if(done)done();}else renderDialogue();}
$('#dialogue-next').onclick=nextDialogue;$('#dialogue').onclick=e=>{if(e.target.closest('button'))return;nextDialogue();};
function transition(place,region=game.region,depth=0,fromExit=false){
 if(!game)return;const previous=game.place;game.place=place;game.region=region;game.dungeonFloor=place==='dungeon'?clamp(depth,0,3):0;
 map=makeMap(region,place,game.dungeonFloor);
 if(map.entry){const point=fromExit?map.exit:map.entry;game.x=point.x;game.y=point.y;}
 else{game.x=place==='route'?(previous==='dungeon'?33:6):18;game.y=place==='route'?16:19;}
 visualPlayer={x:game.x,y:game.y};heldKeys.clear();pathQueue=[];moveCooldown=.3;lastInteraction=null;$('#interact-prompt').classList.add('hidden');save();updateHUD();announceZone();
 if(place==='town'&&!game.flags['entered'+region]){game.flags['entered'+region]=true;showDialogue(CHAPTERS[region].intro,()=>save());}
}
function grant(loot){for(const [id,count] of Object.entries(loot))game.bag[id]=(game.bag[id]||0)+count;save();updateHUD();toast(Object.entries(loot).map(([id,n])=>`${ITEMS[id].name} × ${n}`).join('，'));sfx('get');}
function interact(){if(!game||fight||modalType)return;if(dialogue){nextDialogue();return;}const o=nearest(map,game);if(!o)return;const ch=CHAPTERS[game.region];
 switch(o.action){
  case 'exit':transition(o.to);break;
  case 'stairs':if(o.direction==='back'){if(game.dungeonFloor===0)transition('route');else transition('dungeon',game.region,game.dungeonFloor-1,true);}else transition('dungeon',game.region,game.dungeonFloor+1);break;
  case 'rune':{const result=turnRune(game,o,map.objects.filter(x=>x.action==='seal'));game=result.game;save();sfx('get');toast(`${o.label} → ${RUNE_SYMBOLS[result.value]}${result.opened.length?'。远处的封门打开了！':''}`);break;}
  case 'seal':showDialogue([['古老的封门',gateIsOpen(game,o)?'符柱已经回应彼此。前方的路向你敞开。':'三枚符印尚未同时点亮。附近的石碑，记着符柱应该呈现的模样。']]);break;
  case 'dungeon-lore':showDialogue([[o.label,o.text]]);break;
  case 'dungeon-trainer':{const level=Math.max(2,ch.level+(map.depth||0)+1+(o.levelOffset||0));const team=o.team.map((id,i)=>createMon(id,Math.min(65,level+i%2),game.seed+i));showDialogue([[o.label,'在走到更高的地方之前，让我们用一场对战交换旅途的见闻。']],()=>startBattle(team,{kind:'trainer',name:o.label,trainer:o.id}));break;}
  case 'gate':if(fragmentCount()<3)showDialogue([['阿汐',`通往${ch.dungeon}的门还没有回应。我们需要找到全部 3 份碎片，现在有 ${fragmentCount()} 份。`]]);else transition('dungeon');break;
  case 'story':showDialogue(game.badges.includes(game.region)?[['旅人',ch.lore],['阿汐','下一次相遇的时候，我们又会带来怎样的故事呢？']]:game.region===0?[['洛珈博士','与潮灵相处的第一课，是学会等待。战斗时用「守势」恢复能量，不必每回合都进攻。'],['洛珈博士',ch.task],['洛珈博士','生命不足就回来找栀夏，她会免费照顾你的伙伴。草原上发光的晶体，是你要找的东西。']]:[[ch.warden,ch.problem],['阿汐',ch.task]]);break;
  case 'heal':case 'rest':healParty(game);save();updateHUD();sfx('heal');showDialogue([[o.action==='heal'?'栀夏':'营地旅人','辛苦了。把伙伴交给我，稍稍歇一会儿吧。'],['系统','全队生命、能量和异常状态已恢复。']]);break;
  case 'side-story':openSideStory(o.story);break;
  case 'campfire':if(game.badges.includes(game.region)){healParty(game);save();updateHUD();showDialogue(CAMPFIRE_TALKS[game.region]);}else showDialogue([['阿汐','等星灯点亮，我们再在这里慢慢聊吧。现在先好好休息一下。']],()=>{healParty(game);save();updateHUD();});break;
  case 'trial':openTrial();break;
  case 'shop':openShop();break;
  case 'craft':openCraft();break;
  case 'travel':openMap();break;
  case 'quest':openQuest(o.quest);break;
  case 'resource':game.collected[o.id]=true;grant({[o.item]:1+Math.floor(random(game)*2)});break;
  case 'fragment':game.collected[o.id]=true;game.flags[`fragment${game.region}-${o.fragment}`]=true;grant({shard:1});showDialogue([['阿汐',`找到了，${o.label}。里面有一段很微弱的声音，好像有人在等我们。`],['系统',`已收集 ${fragmentCount()} / 3。${fragmentCount()===3?'现在可以进入'+ch.dungeon+'。':'继续探索这片原野吧。'}`]]);break;
  case 'chest':game.collected[o.id]=true;grant(o.loot);break;
  case 'companion':showDialogue([['阿汐',game.badges.includes(game.region)?ch.lore:fragmentCount()===3?'准备好了吗？无论前面有什么，我们一起去见它。':'我以前以为，旅行就是一直向前走。现在发现，偶尔停下来听人说话，也会遇见很远的地方。'],['阿汐',game.party.length===1?'只有一个伙伴会有点辛苦。遇到野生潮灵时，先削弱它，再用星约石缔约吧。':'你看，大家越来越信任你了。我们已经不是刚离开港口时的样子了。']]);break;
  case 'trainer':{const team=[createMon(ch.wild[o.trainer+1],ch.level+2+o.trainer,game.seed)];if(game.region>1)team.push(createMon(ch.wild[0],ch.level,game.seed+1));showDialogue([[o.label,'在路上相遇，也是一种缘分。来一场认真的切磋吧！']],()=>startBattle(team,{kind:'trainer',name:o.label,trainer:o.id}));break;}
  case 'boss':if(fragmentCount()<3)showDialogue([[ch.warden,'灯印还没有被唤醒。先找回路上失落的三份记忆吧。']]);else showDialogue(game.badges.includes(game.region)?[[ch.warden,'又见面了。让我们看看，这段旅途让彼此成长了多少。']]:ch.before,()=>{const rematch=game.badges.includes(game.region);const level=ch.bossLevel+(rematch?8:0);startBattle(ch.boss.map((s,i)=>createMon(s,level+i,game.seed+i)),{kind:'boss',name:ch.warden,first:!rematch});});break;
 }
}

function openParty(){openModal('同行的伙伴',`<p class="section-note">最多 6 只潮灵同行。领队会跟随你探索。驿站里的伙伴会耐心等你来接它们。</p><div class="grid">${game.party.map((m,i)=>`<div class="card">${monCanvas(m.species)}${typeTag(SPECIES[m.species].element)}<h3>${SPECIES[m.species].name} <small>Lv.${m.level}</small></h3>${hpHTML(m)}<p>${ITEMS[m.equip]?.name||'未佩戴护符'} · 默契 ${m.bond||0}</p><div class="card-actions"><button data-detail="${i}">详细资料</button><button data-lead="${i}" ${i===0?'disabled':''}>设为领队</button><button data-store="${i}" ${game.party.length===1?'disabled':''}>送往驿站</button></div></div>`).join('')}</div><h3 style="margin:24px 0 8px;font-family:var(--serif)">潮灵驿站 · ${game.reserve.length} 位伙伴</h3>${game.reserve.length?`<div class="grid">${game.reserve.map((m,i)=>`<div class="card">${monCanvas(m.species,90)}<h3>${SPECIES[m.species].name} Lv.${m.level}</h3><button class="secondary" data-withdraw="${i}" ${game.party.length>=6?'disabled':''}>加入队伍</button></div>`).join('')}</div>`:'<p class="section-note">队伍满员后，新缔约的潮灵会来到这里。</p>'}`,'party');
 $$('[data-detail]').forEach(b=>b.onclick=()=>openMon(game.party[+b.dataset.detail]));$$('[data-lead]').forEach(b=>b.onclick=()=>{const m=game.party.splice(+b.dataset.lead,1)[0];game.party.unshift(m);save();updateHUD();openParty();});$$('[data-store]').forEach(b=>b.onclick=()=>{if(game.party.length<=1)return;game.reserve.push(game.party.splice(+b.dataset.store,1)[0]);save();updateHUD();openParty();});$$('[data-withdraw]').forEach(b=>b.onclick=()=>{if(game.party.length>=6)return;game.party.push(game.reserve.splice(+b.dataset.withdraw,1)[0]);save();updateHUD();openParty();});}
function hpHTML(m,showStatus=true){return `<div class="hp-bar"><span style="width:${m.hp/stats(m).hp*100}%;background:${m.hp/stats(m).hp<.25?'#d58d7e':'#89c8ac'}"></span></div><div class="hp-meta"><span>${showStatus?(m.hp<=0?'失去战斗能力':STATUS[m.status]||'状态良好'):'生命'}</span><span>${m.hp} / ${stats(m).hp} HP</span></div>`;}
function openMon(m){const s=SPECIES[m.species],v=stats(m);openModal(s.name,`<div style="display:flex;gap:25px;align-items:center;flex-wrap:wrap"><div>${monCanvas(m.species,190)}</div><div style="flex:1;min-width:200px">${typeTag(s.element)}<h3 style="margin:14px 0;font-family:var(--serif)">Lv.${m.level} · 第 ${s.stage} 阶形态</h3><p class="section-note">${s.lore}</p>${hpHTML(m)}<div class="stats-grid">${Object.entries(v).map(([k,n])=>`<span>${{hp:'生命',atk:'攻击',def:'防御',spd:'速度'}[k]}<b>${n}</b></span>`).join('')}</div></div></div><p class="section-note" style="margin-top:20px">成长 ${m.xp} / ${xpNeed(m)} · ${s.evolve?`到达 ${s.evolveAt} 级将进化为 ${SPECIES[s.evolve].name}`:'已经成长为最终形态'} · 默契 ${m.bond||0}</p>${moveList(m).map(k=>`<div class="card-row"><div class="item-icon" style="color:${ELEMENTS[MOVES[k].element]?.color||'#ddd'}">✧</div><div class="grow"><h3>${MOVES[k].name} <small style="color:var(--gold)">能量 ${MOVES[k].cost}</small></h3><p>${MOVES[k].desc} ${MOVES[k].power?'威力 '+MOVES[k].power:''}</p></div></div>`).join('')}<div class="card-actions"><button id="equip-mon">佩戴护符</button><button id="back-party">返回队伍</button></div>`,'mon');$('#back-party').onclick=openParty;$('#equip-mon').onclick=()=>{const options=Object.keys(ITEMS).filter(id=>ITEMS[id].equip&&game.bag[id]>0);openModal('选择护符',`<p class="section-note">当前：${ITEMS[m.equip]?.name||'未佩戴'}。更换时会归还旧护符。</p>${options.map(id=>`<div class="card-row"><div class="grow"><h3>${ITEMS[id].name}</h3><p>${ITEMS[id].desc}</p></div><button class="secondary" data-equip="${id}">佩戴</button></div>`).join('')||'<p class="section-note">还没有护符，可以在杂货店购买。</p>'}<button class="secondary" id="unequip">取下护符</button>`);$$('[data-equip]').forEach(b=>b.onclick=()=>{const old=stats(m).hp;if(m.equip)game.bag[m.equip]=(game.bag[m.equip]||0)+1;m.equip=b.dataset.equip;game.bag[m.equip]--;m.hp=Math.min(stats(m).hp,Math.ceil(m.hp*stats(m).hp/old));save();updateHUD();openMon(m);});$('#unequip').onclick=()=>{if(m.equip){game.bag[m.equip]=(game.bag[m.equip]||0)+1;m.equip=null;m.hp=Math.min(stats(m).hp,m.hp);save();updateHUD();}openMon(m);};};}
function openBag(){openModal('旅行背包',`<div class="tab-row"><button id="bag-craft">调配与合成</button><span style="margin-left:auto;color:var(--gold);padding:8px">◈ ${game.gold} 星砂</span></div>${Object.entries(ITEMS).filter(([id])=>game.bag[id]>0).map(([id,item])=>`<div class="card-row"><div class="item-icon">${item.icon}</div><div class="grow"><h3>${item.name}</h3><p>${item.desc}</p></div><span class="count">× ${game.bag[id]}</span>${item.heal||item.cleanse||item.revive?`<button class="secondary" data-use="${id}">使用</button>`:''}</div>`).join('')}`,'bag');$('#bag-craft').onclick=openCraft;$$('[data-use]').forEach(b=>b.onclick=()=>chooseItemTarget(b.dataset.use));}
function itemCanTarget(item,mon){return item.revive?mon.hp<=0:item.heal?mon.hp>0&&mon.hp<stats(mon).hp:item.cleanse?!!mon.status:false;}
function chooseItemTarget(id,inBattle=false){const party=inBattle?fight.party:game.party;openModal('使用'+ITEMS[id].name,`<p class="section-note">${ITEMS[id].desc}</p>${party.map((m,i)=>`<div class="card-row">${monCanvas(m.species,64)}<div class="grow"><h3>${SPECIES[m.species].name}</h3>${hpHTML(m)}</div><button class="secondary" data-target="${i}" ${itemCanTarget(ITEMS[id],m)?'':'disabled'}>选择</button></div>`).join('')}`,'target');$$('[data-target]').forEach(b=>b.onclick=()=>{const idx=+b.dataset.target;if(inBattle){closeModal();battleAction({type:'item',item:id,target:idx});return;}const m=game.party[idx],item=ITEMS[id];if(!game.bag[id])return toast('这件道具已经用完了。');if(item.revive){if(m.hp>0)return toast('伙伴还没有倒下，不需要使用。');m.hp=Math.ceil(stats(m).hp*.5);m.status=null;}else if(item.heal){if(m.hp===0)return toast('请先使用回声种唤醒伙伴。');if(m.hp===stats(m).hp)return toast('生命已经恢复满了。');m.hp=Math.min(stats(m).hp,m.hp+item.heal);}else if(item.cleanse){if(!m.status)return toast('伙伴没有异常状态。');m.status=null;}game.bag[id]--;save();updateHUD();sfx('heal');toast('使用成功。');openBag();});}
function openCraft(){openModal('潮灵工坊',`<p class="section-note">从原野拾取月息草与潮晶碎片，调配旅途所需。配方随身携带，在背包里也能合成。</p>${RECIPES.map(r=>`<div class="card-row"><div class="item-icon">${ITEMS[r.id].icon}</div><div class="grow"><h3>${ITEMS[r.id].name} × ${r.count}</h3><p>${Object.entries(r.needs).map(([id,n])=>`${ITEMS[id].name} ${game.bag[id]||0}/${n}`).join(' · ')}</p></div><button class="secondary" data-recipe="${r.id}" ${Object.entries(r.needs).some(([id,n])=>(game.bag[id]||0)<n)?'disabled':''}>合成</button></div>`).join('')}`,'craft');$$('[data-recipe]').forEach(b=>b.onclick=()=>{const r=RECIPES.find(x=>x.id===b.dataset.recipe);if(Object.entries(r.needs).some(([id,n])=>(game.bag[id]||0)<n))return;for(const [id,n] of Object.entries(r.needs))game.bag[id]-=n;grant({[r.id]:r.count});openCraft();});}
function openShop(){const stock=['potion','superpotion','revive','cure','orb','greatorb','emberCharm','shellCharm','featherCharm','heartCharm'];openModal('星约杂货',`<p class="section-note">松石：「好道具不是让你走得更快，是让你走得更远。」 <b style="color:var(--gold)">◈ ${game.gold} 星砂</b></p>${stock.map(id=>`<div class="card-row"><div class="item-icon">${ITEMS[id].icon}</div><div class="grow"><h3>${ITEMS[id].name} <small style="color:var(--gold)">◈ ${ITEMS[id].price}</small></h3><p>${ITEMS[id].desc} · 持有 ${game.bag[id]||0}</p></div><button class="secondary" data-buy="${id}" ${game.gold<ITEMS[id].price?'disabled':''}>购买</button></div>`).join('')}`,'shop');$$('[data-buy]').forEach(b=>b.onclick=()=>{const id=b.dataset.buy;if(game.gold<ITEMS[id].price)return;game.gold-=ITEMS[id].price;grant({[id]:1});openShop();});}

function openMap(){openModal('群岛航图',`<p class="section-note">点亮一座岛的星灯，即可沿着罗盘指引前往下一座岛。已抵达的群岛可随时自由往返。</p><div class="map-grid">${CHAPTERS.map((c,i)=>{const unlocked=i===0||game.badges.includes(i-1);return `<div class="island-card ${!unlocked?'locked':''}"><span class="island-number">0${i+1}</span><h3>${c.island} ${game.badges.includes(i)?'✧':''}</h3><p>${c.name}<br>野生潮灵 Lv.${c.level}–${c.level+3}</p><button class="secondary" data-travel="${i}" ${!unlocked?'disabled':''}>${!unlocked?'航线尚未点亮':i===game.region?'返回本岛港口':'启程前往'}</button></div>`;}).join('')}</div>`,'map','沿着星灯，去往更远的地方');$$('[data-travel]').forEach(b=>b.onclick=()=>{const region=+b.dataset.travel;if(region>0&&!game.badges.includes(region-1))return;closeModal();transition('town',region);});}
function openQuest(id){const q=SIDEQUESTS.find(q=>q.id===id);const state=game.quest[id],ready=questReady(game,q);openModal(q.name,`<span class="eyebrow">${q.giver} · ${CHAPTERS[q.region].island}</span><p class="section-note" style="margin-top:18px">“${q.text}”</p><div class="quest-card"><h3>${q.kind==='deliver'?`交付 ${ITEMS[q.item].name} × ${q.need}`:q.kind==='capture'?`缔约 ${SPECIES[q.species].name}`:`在本岛赢得 ${q.need} 场战斗`}</h3><p>${q.kind==='deliver'?`持有 ${game.bag[q.item]||0}`:q.kind==='capture'?ready?'已经认识这位伙伴':'尚未缔约':`已完成 ${game.wins[q.region]||0} / ${q.need}`}</p><small>报酬：${q.reward} 星砂 · 辉光星约石 × 1</small></div><button class="primary" id="quest-button" ${state==='done'?'disabled':''}>${state==='done'?'委托已完成':!state?'接受委托':ready?'交付并领取报酬':'继续寻找'}</button>`,'quest');$('#quest-button').onclick=()=>{if(!state){game.quest[id]='active';save();openQuest(id);return;}if(!ready){closeModal();return;}if(state==='done')return;if(q.kind==='deliver')game.bag[q.item]-=q.need;game.quest[id]='done';game.gold+=q.reward;grant({greatorb:1});showDialogue([[q.giver,'谢谢你。不是每一件小事都会写进传说，但它们真的改变了我的今天。']]);closeModal();};}
function openJournal(){const ch=CHAPTERS[game.region],quests=SIDEQUESTS.filter(q=>q.region===game.region||game.quest[q.id]);openModal('旅途手记',`<div class="tab-row"><button id="open-memories">路上拾起的故事 · ${Object.keys(game.stories||{}).length}</button></div><div class="quest-card"><small>主线 · 第 ${game.region+1} 章</small><h3>${ch.name}</h3><p>${ch.problem}</p><p style="color:var(--gold)">${game.badges.includes(game.region)?'本岛星灯已经点亮。可以启程前往下一座岛。':ch.task+`（${fragmentCount()}/3）`}</p></div><h3 style="margin:24px 0 14px;font-family:var(--serif)">路上遇见的人</h3>${quests.map(q=>`<button class="quest-card" style="display:block;width:100%;text-align:left" data-openquest="${q.id}"><small>${CHAPTERS[q.region].island} · ${game.quest[q.id]==='done'?'已完成':game.quest[q.id]?'进行中':'可接受'}</small><h3>${q.name}</h3><p>${q.text}</p></button>`).join('')}<h3 style="margin:24px 0 14px;font-family:var(--serif)">已经点亮的灯</h3>${game.badges.map(i=>`<div class="quest-card"><h3>✧ ${CHAPTERS[i].reward}</h3><p>${CHAPTERS[i].lore}</p></div>`).join('')||'<p class="section-note">你的第一盏灯，正在等你。</p>'}`,'journal');$$('[data-openquest]').forEach(b=>b.onclick=()=>openQuest(b.dataset.openquest));$('#open-memories').onclick=openMemories;}
function openDex(element='all'){const ids=Object.keys(SPECIES).filter(id=>element==='all'||SPECIES[id].element===element);openModal('潮灵图鉴',`<p class="section-note">已相遇 ${new Set([...game.seen,...game.caught]).size} / ${Object.keys(SPECIES).length} · 已缔约 ${game.caught.length}。每一个小小的生命，都有自己的故事。</p><div class="tab-row"><button data-element="all" class="${element==='all'?'active':''}">全部</button>${Object.keys(ELEMENTS).map(e=>`<button data-element="${e}" class="${element===e?'active':''}">${ELEMENTS[e].name}</button>`).join('')}</div><div class="dex-grid">${ids.map(id=>{const known=game.caught.includes(id)||game.seen.includes(id);return `<button class="dex-cell ${known?'':'unknown'}" data-dex="${id}"><small>No.${String(Object.keys(SPECIES).indexOf(id)+1).padStart(3,'0')} ${game.caught.includes(id)?'✦':''}</small>${monCanvas(id,100)}<p>${known?SPECIES[id].name:'尚未相遇'}</p></button>`;}).join('')}</div>`,'dex');$$('[data-element]').forEach(b=>b.onclick=()=>openDex(b.dataset.element));$$('[data-dex]').forEach(b=>b.onclick=()=>{const s=SPECIES[b.dataset.dex];if(!game.caught.includes(s.id)&&!game.seen.includes(s.id))return toast('继续探索，未来也许会遇见它。');const locations=CHAPTERS.filter(c=>c.wild.some(id=>SPECIES[id].family===s.family)).map(c=>c.route).join('、');openModal(s.name,`${monCanvas(s.id,210)}<div style="text-align:center">${typeTag(s.element)}<p class="section-note" style="margin:20px">${s.lore}</p><p class="section-note">栖息地：${locations||'需要通过进化认识它'}<br>${s.stage>1?'此形态主要由伙伴成长进化而来。':''}</p></div>`,'dex-entry');});}

function openSideStory(id){
 const story=SIDE_STORIES.find(s=>s.id===id);if(!story)return;
 game.stories??={};game.flags['met-'+id]=true;
 if(game.stories[id]!==undefined){const choice=story.choices[game.stories[id]];showDialogue([...story.epilogue,['旅途手记',choice.memory]]);return;}
 showDialogue(story.opening,()=>{
  openModal(story.title,`<p class="section-note">${escape(story.hook)}</p><div class="grid" style="grid-template-columns:1fr 1fr">${story.choices.map((choice,i)=>`<button class="card starter-card" data-story-choice="${i}"><span class="eyebrow">${i===0?'一种回应':'另一种回应'}</span><h3>${escape(choice.label)}</h3><p>用自己的方式回应这段相遇。</p></button>`).join('')}</div>`,'story-choice',story.giver);
  $$('[data-story-choice]').forEach(button=>button.onclick=()=>{
   if(game.stories[id]!==undefined)return;
   const index=+button.dataset.storyChoice,result=completeStory(game,id,index),choice=result.choice;game=result.game;
   closeModal();save();updateHUD();showDialogue([...choice.reply,...story.epilogue,['旅途手记',choice.memory]],()=>{sfx('get');toast(`相遇已记入手记。获得 ${choice.reward.gold} 星砂与旅途补给。`);});
  });
 });
}
function openMemories(){const completed=game.stories||{};openModal('路上拾起的故事',`<p class="section-note">已留下 ${Object.keys(completed).length} / ${SIDE_STORIES.length} 段回忆。有些问题没有标准答案，但每一次认真回应都会留下痕迹。</p>${SIDE_STORIES.filter(s=>s.region<=game.region||game.badges.includes(s.region)).map(s=>{const choice=s.choices[completed[s.id]];return `<div class="quest-card"><small>${CHAPTERS[s.region].island} · ${CHAPTERS[s.region][s.place]} · ${choice?'已完成':'等待相遇'}</small><h3>${s.title}</h3><p>${choice?escape(choice.memory):escape(s.hook)}</p><p>${s.giver}</p>${choice?`<button class="text-button" data-reread="${s.id}">重读这段回忆 →</button>`:''}</div>`;}).join('')}`,'memories','人与人之间，也会亮起一盏灯');$$('[data-reread]').forEach(b=>b.onclick=()=>{closeModal();openSideStory(b.dataset.reread);});}
function openTrial(){if(!game.ending){showDialogue([['遥远的声音','当八盏星灯都获得回应时，群星将为你开放新的航路。']]);return;}
 const floor=(game.trial||0)+1,level=Math.min(65,52+Math.floor(floor/2));openModal('星海试炼',`<div class="results-summary"><div class="big-star">✦</div><h3>第 ${floor} 阶 · 未知的海</h3><p>潮灵等级 ${level}–${Math.min(65,level+2)}。<br>连续挑战不同属性的队伍，检验一路积累的默契。<br>当前纪录：${game.trial||0} 阶。胜利后可自由休息，再来继续。</p><button class="primary" id="begin-trial">回应群星的挑战 →</button></div>`,'trial');$('#begin-trial').onclick=()=>{const families=Object.values(SPECIES).filter(s=>s.stage===3),team=[];for(let i=0;i<Math.min(6,3+Math.floor(floor/4));i++){const s=families[(floor*3+i*5)%families.length];team.push(createMon(s.id,Math.min(65,level+i%3),game.seed+i));}closeModal();startBattle(team,{kind:'trial',name:`星海试炼 · 第 ${floor} 阶`,floor});};
}

function startBattle(enemies,context){
 if(!game.party.some(m=>m.hp>0)){healParty(game);updateHUD();return toast('伙伴们需要休息，已经为你送回诊所治疗。');}
 save();pendingBattle=null;battleEffect=null;battleEvents=[];$('#battle-screen').classList.remove('animating');fight=makeBattle(game,enemies,context);for(const m of enemies)if(!game.seen.includes(m.species))game.seen.push(m.species);battleMenu='root';heldKeys.clear();pathQueue=[];$('#world-ui').classList.add('hidden');$('#mobile-controls').classList.add('hidden');$('#battle-screen').classList.remove('hidden');$('#game-nav').classList.add('hidden');sfx('battle');renderBattle();}
function renderBattle(){if(!fight)return;const p=fight.party[fight.activeP],e=fight.enemies[fight.activeE];$('#battle-location').textContent=fight.context.name||CHAPTERS[game.region][game.place]+' · 野生相遇';$('#battle-weather').textContent=WEATHER[fight.weather].icon+' '+WEATHER[fight.weather].name;$('#turn-label').textContent=fight.outcome?'这场相遇的结尾':`第 ${fight.turn+1} 回合 · 你们的选择`;
 const statusHTML=m=>`<div class="status-title"><strong>${SPECIES[m.species].name}</strong><small>Lv.${m.level}</small></div>${typeTag(SPECIES[m.species].element)}${m.status?`<span class="status-tag">${STATUS[m.status]}</span>`:''}${hpHTML(m,false)}<div class="energy-dots" title="能量 ${m.energy}/5">${'◆'.repeat(m.energy)}<span style="opacity:.2">${'◇'.repeat(5-m.energy)}</span>${m.shield?' <small style="font-size:9px;letter-spacing:0">护盾</small>':''}</div>`;
 $('#enemy-status').innerHTML=statusHTML(e);$('#player-status').innerHTML=statusHTML(p);$('#battle-log').innerHTML=fight.log.map(l=>`<p>${escape(l)}</p>`).join('');$('#battle-log').scrollTop=$('#battle-log').scrollHeight;
 let html='';
 if(fight.outcome){html=`<button class="attack-button" id="battle-finish" style="grid-column:1/-1;text-align:center">${fight.outcome==='win'?'战斗胜利 · 继续旅程':fight.outcome==='capture'?'新的约定 · 欢迎伙伴':fight.outcome==='lose'?'返回诊所 · 重新出发':'平安离开 · 继续探索'} →</button>`;}
 else if(battleMenu==='moves'){html=moveList(p).map((key,i)=>{const m=MOVES[key],eff=effectiveness(m.element,SPECIES[e.species].element);return `<button data-move="${key}" ${m.cost>p.energy?'disabled':''} style="border-left:3px solid ${ELEMENTS[m.element]?.color||'#c5cbbb'}">${i+1}. ${m.name}<small>◆ ${m.cost}　${m.power?'威力 '+m.power:'辅助'}${eff>1?' · 克制':eff<1?' · 抵抗':''}</small></button>`;}).join('')+'<button class="battle-back" data-battle-menu="root">返回指令</button>';}
 else if(battleMenu==='bag'){html=['potion','superpotion','revive','cure'].filter(id=>fight.inventory[id]>0).map(id=>`<button data-battle-item="${id}">${ITEMS[id].name}<small>持有 ${fight.inventory[id]} · ${ITEMS[id].desc}</small></button>`).join('')+'<button class="battle-back" data-battle-menu="root">返回指令</button>';}
 else if(battleMenu==='capture'){html=['orb','greatorb'].map(id=>`<button data-capture="${id}" ${!fight.inventory[id]?'disabled':''}>${ITEMS[id].name}<small>持有 ${fight.inventory[id]||0} · 生命越低越易缔约</small></button>`).join('')+'<button class="battle-back" data-battle-menu="root">返回指令</button>';}
 else if(battleMenu==='switch'){html=fight.party.map((m,i)=>`<button data-switch="${i}" ${i===fight.activeP||m.hp===0?'disabled':''}>${SPECIES[m.species].name}<small>Lv.${m.level} · ${m.hp}/${stats(m).hp} HP</small></button>`).join('')+'<button class="battle-back" data-battle-menu="root">返回指令</button>';}
 else{html='<button class="attack-button" data-battle-menu="moves">1. 技能 <small style="color:#39594f">选择潮灵的行动</small></button><button data-action="guard">2. 守势 <small>能量 +2 · 受到伤害降低</small></button><button data-battle-menu="switch">3. 换人 <small>让其他伙伴加入战斗</small></button><button data-battle-menu="bag">4. 道具 <small>恢复、唤醒与净化</small></button>'+(fight.context.kind==='wild'?'<button data-battle-menu="capture">缔约 <small>让新伙伴认识你</small></button><button data-action="run">离开 <small>尝试退出野生战斗</small></button>':'');}
 $('#battle-actions').innerHTML=html;$$('[data-battle-menu]').forEach(b=>b.onclick=()=>{battleMenu=b.dataset.battleMenu;renderBattle();});$$('[data-move]').forEach(b=>b.onclick=()=>battleAction({type:'move',move:b.dataset.move}));$$('[data-action]').forEach(b=>b.onclick=()=>battleAction({type:b.dataset.action}));$$('[data-capture]').forEach(b=>b.onclick=()=>battleAction({type:'capture',item:b.dataset.capture}));$$('[data-switch]').forEach(b=>b.onclick=()=>battleAction({type:'switch',index:+b.dataset.switch}));$$('[data-battle-item]').forEach(b=>b.onclick=()=>chooseItemTarget(b.dataset.battleItem,true));if($('#battle-finish'))$('#battle-finish').onclick=finishBattle;
}
let battleEvents=[];
function commitBattleTurn(){
 if(!pendingBattle)return;fight=pendingBattle;pendingBattle=null;battleEffect=null;$('#battle-screen').classList.remove('animating');$('#battle-actions').removeAttribute('aria-busy');battleMenu='root';
 if(fight.outcome){const result=settleBattle(game,fight);game=result.game;fight.party=clone(game.party);battleEvents=result.events;fight.log=[...fight.log,...battleEvents];save();if(['win','capture'].includes(fight.outcome))sfx('win');}renderBattle();
}
function battleAction(action){
 if(pendingBattle)return;const next=takeTurn(fight,action);if(next.error)return toast(next.error);
 pendingBattle=next;const events=next.events||[];battleEffect={start:frameTime,events,seed:next.seed};
 if(action.type==='switch')fight.activeP=action.index;
 $('#battle-screen').classList.add('animating');$('#battle-actions').setAttribute('aria-busy','true');for(const button of $$('#battle-actions button'))button.disabled=true;sfx('hit');
 if(game.reduceMotion||!events.length)commitBattleTurn();
}

function finishBattle(){if(!fight?.outcome)return;const previous=fight;fight=null;visualPlayer={x:game.x,y:game.y};map=makeMap(game.region,game.place,game.dungeonFloor||0);$('#battle-screen').classList.add('hidden');$('#world-ui').classList.remove('hidden');$('#game-nav').classList.remove('hidden');$('#mobile-controls').classList.remove('hidden');updateHUD();save();moveCooldown=.7;lastStepCount=game.steps;canvas.focus();
 if(previous.outcome==='win'&&previous.context.kind==='boss'&&previous.context.first){showDialogue(CHAPTERS[game.region].after,()=>{if(game.ending)showDialogue(ENDING,()=>{toast('主线完结。感谢你陪伴这段旅途。');save();});else toast('新的航线已开放。前往港口，继续旅程。');});}
 else if(battleEvents.length)toast(battleEvents[battleEvents.length-1]);}
function drawBattle(t){drawBattleScene(ctx,view.w,view.h,game,fight,t,game.reduceMotion?null:battleEffect);}

function openSettings(){if(pendingBattle)return;openModal('旅途设置',game?`<div class="settings-row"><div><h3>保存进度</h3><p>浏览器自动存档，也可以手动保存与导出备份。</p></div><button class="secondary" id="manual-save">立即保存</button></div><div class="settings-row"><div><h3>存档文件</h3><p>换设备或清理浏览器前，先导出你的旅程。</p></div><div class="card-actions"><button id="export-save">导出存档</button><button id="import-save">导入存档</button></div></div><div class="settings-row"><div><h3>旅途旋律</h3><p>轻柔的原创合成旋律与战斗音效。</p></div><button class="secondary" id="toggle-sound">${game.sound?'已开启':'已关闭'}</button></div><div class="settings-row"><div><h3>画面质量</h3><p id="live-performance">正在测量实际帧率</p></div><select id="quality-select" class="quality-select"><option value="high" ${!game.quality||game.quality==='high'?'selected':''}>精细 · Retina</option><option value="balanced" ${game.quality==='balanced'?'selected':''}>均衡</option><option value="performance" ${game.quality==='performance'?'selected':''}>流畅优先</option></select></div><div class="settings-row"><div><h3>减少动态效果</h3><p>减弱飘动与角色动画。</p></div><button class="secondary" id="toggle-motion">${game.reduceMotion?'已开启':'已关闭'}</button></div><div class="settings-row"><div><h3>旅程记录</h3><p>游戏时间 ${Math.floor(game.playtime/3600)} 小时 ${Math.floor(game.playtime/60)%60} 分钟 · 步数 ${game.steps} · 版本 ${VERSION}</p></div></div><div class="card-actions"><button id="return-title">保存并返回标题</button></div>`:`<p class="section-note">开始旅程后，这里可以保存进度、导出存档和调整声音。</p><button class="secondary" id="settings-import">导入存档</button>`,'settings');if(!game){$('#settings-import').onclick=()=>$('#save-file').click();return;}$('#quality-select').onchange=e=>{game.quality=e.target.value;resize();metrics.reset();save();};$('#manual-save').onclick=()=>save(true);$('#export-save').onclick=()=>downloadSave();$('#import-save').onclick=()=>$('#save-file').click();$('#toggle-sound').onclick=()=>{toggleSound();openSettings();};$('#toggle-motion').onclick=()=>{game.reduceMotion=!game.reduceMotion;save();openSettings();};$('#return-title').onclick=()=>{if(fight&&!fight.outcome)return toast('请先完成当前战斗。');save();savedText=saveEnvelope(game);closeModal();stopMusic();game=null;fight=null;dialogue=null;$('#title-screen').classList.remove('hidden');$('#continue-button').classList.remove('hidden');for(const id of ['world-ui','game-nav','battle-screen','dialogue','mobile-controls'])$('#'+id).classList.add('hidden');};}
function openHelp(){openModal('给第一次启程的你',`<div class="help-grid"><div><b>探索</b>WASD / 方向键移动，Shift 奔跑。点击地图也会自动寻路。靠近人物或发光物体，按 E / 空格互动。</div><div><b>战斗</b>每只潮灵有 5 点能量。技能消耗能量，跃击回复 1 点。守势回复 2 点，并暂时降低伤害。</div><div><b>缔约</b>野外战斗中先削弱对手，再选择缔约。状态异常会提升成功率。队伍最多 6 只，其余进入驿站。</div><div><b>成长</b>胜利后全队获得经验。16 级与 32 级会进化，9、18、27 级习得新技能。护符可提升属性。</div><div><b>探索目标</b>每座岛有三份失落记忆。收齐后进入遗迹挑战守灯人，点亮星灯，开放下一条航线。</div><div><b>休息与存档</b>港口诊所免费治疗。移动和战斗后会自动保存。设置中可导出 JSON 存档，防止浏览器清理。</div></div><h3 style="margin:24px 0 12px;font-family:var(--serif)">属性克制 · 攻击获得 1.6 倍效果</h3><div class="help-grid">${Object.entries(ELEMENTS).map(([id,e])=>`<div><b style="color:${e.color}">${e.name}属性</b>克制 ${e.strong.map(x=>ELEMENTS[x].name).join('、')}<br>对 ${e.weak.map(x=>ELEMENTS[x].name).join('、')} 应谨慎</div>`).join('')}</div><p class="section-note" style="margin-top:20px">天气会增强对应属性。灼伤降低攻击并持续损伤；中毒持续损伤；麻痹与缠绕降低速度；入眠会短暂无法行动。换人也会消耗一个回合。</p>`,'help');}
$('#settings-button').onclick=openSettings;$('#help-button').onclick=openHelp;$('#battle-help').onclick=openHelp;$('#journal-shortcut').onclick=()=>game&&openJournal();$('#home-mark').onclick=e=>{e.preventDefault();openSettings();};
const menus={party:openParty,bag:openBag,map:openMap,journal:openJournal,dex:openDex};$$('[data-menu]').forEach(b=>b.onclick=()=>{if(game&&!fight&&!dialogue)menus[b.dataset.menu]();});

function startMusic(){if(!game?.sound||document.hidden)return;try{soundContext??=new(window.AudioContext||window.webkitAudioContext)();soundContext.resume();if(musicTimer)return;const notes=[60,67,72,76,74,67,64,69,72,79,76,67,62,69,74,77];musicTimer=setInterval(()=>{if(!game?.sound)return;const n=notes[musicStep++%notes.length]-(fight?12:0);tone(n,.45,.022,'sine');if(musicStep%4===1)tone(n-12,1.65,.012,'triangle');},fight?340:540);}catch{}}
function stopMusic(){if(musicTimer)clearInterval(musicTimer);musicTimer=null;}
function tone(midi,duration=.1,volume=.03,type='sine'){if(!soundContext||!game?.sound)return;const o=soundContext.createOscillator(),gain=soundContext.createGain(),now=soundContext.currentTime;o.type=type;o.frequency.value=440*2**((midi-69)/12);gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime(volume,now+.015);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);o.connect(gain);gain.connect(soundContext.destination);o.start(now);o.stop(now+duration+.03);}
function sfx(kind){const sequence={talk:[76],get:[72,79,84],heal:[60,67,72,79],hit:[43,40],win:[67,72,76,79,84],battle:[48,55,60]}[kind]||[70];sequence.forEach((n,i)=>setTimeout(()=>tone(n,kind==='talk'?.06:.18,kind==='talk'?.015:.04,'triangle'),i*65));}
function toggleSound(){if(!game)return toast('开始旅程后可以开启音乐。');game.sound=!game.sound;$('#sound-button').textContent=game.sound?'♫':'♩';if(game.sound)startMusic();else stopMusic();save();}
$('#sound-button').onclick=toggleSound;

function move(dx,dy){if(!game||fight||dialogue||modalType)return false;game.facing=dx>0?'right':dx<0?'left':dy>0?'down':'up';const x=game.x+dx,y=game.y+dy;if(!canWalk(map,game,x,y))return false;game.x=x;game.y=y;game.steps++;walkingUntil=frameTime+.2;
 if(['route','dungeon'].includes(game.place)&&game.steps-lastStepCount>12&&['grass','flowers','snow','sand','stone'].includes(tileKind(map,x,y))&&random(game)<(game.place==='dungeon'?.035:.075)){lastStepCount=game.steps;const ch=CHAPTERS[game.region],ids=ch.wild,id=ids[Math.floor(random(game)*ids.length)],level=ch.level+(game.place==='dungeon'?game.dungeonFloor:0)+Math.floor(random(game)*4);let species=id;if(level>=32)species=id+'_3';else if(level>=16)species=id+'_2';startBattle([createMon(species,level,game.seed)],{kind:'wild'});}
 if(game.steps%20===0&&!fight)save();return true;}
function routeTo(tx,ty){const start=[game.x,game.y],queue=[start],visited=new Set([start.join(',')]),parents=new Map();let dest=null;while(queue.length){const [x,y]=queue.shift();if(x===tx&&y===ty){dest=[x,y];break;}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,key=nx+','+ny;if(visited.has(key)||!canWalk(map,game,nx,ny))continue;visited.add(key);parents.set(key,[x,y]);queue.push([nx,ny]);}}if(!dest)return;const path=[];while(dest[0]!==start[0]||dest[1]!==start[1]){path.unshift(dest);dest=parents.get(dest.join(','));}pathQueue=path;}
canvas.addEventListener('pointerdown',e=>{if(!game||fight||dialogue||modalType)return;const rect=canvas.getBoundingClientRect(),cam=camera({...game,x:visualPlayer.x,y:visualPlayer.y},view.w,view.h,map),tx=Math.floor((e.clientX-rect.left+cam.x)/TILE),ty=Math.floor((e.clientY-rect.top+cam.y)/TILE);const near=map.objects.find(o=>o.action&&Math.hypot(o.x-tx,o.y-ty)<1.5);if(near&&Math.hypot(near.x-game.x,near.y-game.y)<2.2)return interact();if(!canWalk(map,game,tx,ty)){for(const [dx,dy] of [[0,1],[1,0],[-1,0],[0,-1]])if(canWalk(map,game,tx+dx,ty+dy)){routeTo(tx+dx,ty+dy);return;}}else routeTo(tx,ty);canvas.focus();});
document.addEventListener('keydown',e=>{
 if(e.target.matches('input,textarea,select'))return;const key=e.key.toLowerCase();
 if(key==='escape'){e.preventDefault();if(modalType)closeModal();else if(fight){battleMenu='root';renderBattle();}else if(game&&!dialogue)openSettings();return;}
 if(modalType)return;
 if(['arrowup','arrowdown','arrowleft','arrowright',' ','w','a','s','d'].includes(key))e.preventDefault();
 if(dialogue){if(['e',' ','enter'].includes(key)){e.preventDefault();if(!e.repeat)nextDialogue();}return;}
 if(fight){if(!e.repeat&&/^[1-4]$/.test(key))$('#battle-actions').querySelectorAll('button:not(.battle-back)')[+key-1]?.click();return;}
 if(!game)return;
 if(!e.repeat){if(key==='e'||key===' '){interact();return;}const shortcut={p:'party',b:'bag',m:'map',j:'journal',l:'dex'}[key];if(shortcut){menus[shortcut]();return;}}
 heldKeys.add(key);pathQueue=[];
});
document.addEventListener('keyup',e=>heldKeys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>heldKeys.clear());
$$('[data-dir]').forEach(b=>{const key={up:'w',down:'s',left:'a',right:'d'}[b.dataset.dir];b.onpointerdown=e=>{e.preventDefault();heldKeys.add(key);b.setPointerCapture(e.pointerId);};b.onpointerup=()=>heldKeys.delete(key);b.onpointercancel=()=>heldKeys.delete(key);});$('#touch-interact').onclick=interact;$('#interact-prompt').onclick=interact;
document.addEventListener('visibilitychange',()=>{heldKeys.clear();metrics.reset();if(document.hidden){save();stopMusic();}else if(game?.sound)startMusic();});window.addEventListener('pagehide',()=>save());
function loop(ms){if(document.hidden){lastFrame=ms;requestAnimationFrame(loop);return;}const drawStart=performance.now();const dt=Math.min((ms-lastFrame)/1000,.05);lastFrame=ms;frameTime=ms/1000;moveCooldown-=dt;
 if(game&&!document.hidden){if(!modalType)game.playtime+=dt;if(frameTime-lastSaveTick>45&&!fight){lastSaveTick=frameTime;save();}}
 if(game&&!fight&&!dialogue&&!modalType){
  if(moveCooldown<=0){let dx=0,dy=0;if(heldKeys.has('w')||heldKeys.has('arrowup'))dy=-1;else if(heldKeys.has('s')||heldKeys.has('arrowdown'))dy=1;else if(heldKeys.has('a')||heldKeys.has('arrowleft'))dx=-1;else if(heldKeys.has('d')||heldKeys.has('arrowright'))dx=1;else if(pathQueue.length){const [x,y]=pathQueue.shift();dx=x-game.x;dy=y-game.y;}if(dx||dy){move(dx,dy);moveCooldown=heldKeys.has('shift')?.085:.15;}}
  const o=nearest(map,game),label=o?o.label+(o.action==='rune'?' · '+RUNE_SYMBOLS[runeValue(game,o)]:''):'',key=(o?.id||'')+label;if(key!==lastInteraction){lastInteraction=key;$('#interact-prompt').classList.toggle('hidden',!o);if(o){$('#interact-prompt').innerHTML='<kbd>E</kbd>'+escape(label);$('#interact-prompt').setAttribute('aria-label','互动：'+label);}}
 }
 if(game){visualPlayer.x=game.reduceMotion?game.x:easePosition(visualPlayer.x,game.x,dt);visualPlayer.y=game.reduceMotion?game.y:easePosition(visualPlayer.y,game.y,dt);}
 if(pendingBattle&&frameTime-battleEffect.start>=battleEffect.events.length*.48+.08)commitBattleTurn();
 const t=game?.reduceMotion?0:frameTime;if(!modalType||renderDirty){if(!game)drawTitleVista(ctx,view.w,view.h,t);else if(fight)drawBattle(t);else drawWorld(ctx,view.w,view.h,map,{...game,x:visualPlayer.x,y:visualPlayer.y},t,{walking:frameTime<walkingUntil});renderDirty=false;}
 if(!modalType)metrics.record(ms,performance.now()-drawStart);if(frameTime-lastMetricsUpdate>1){lastMetricsUpdate=frameTime;const m=metrics.summary();$('#perf-indicator').textContent=m.fps?`${m.fps} FPS · ${game?.quality==='performance'?'流畅':game?.quality==='balanced'?'均衡':'精细'}`:'测量帧率中';$('#perf-indicator').title=`实际采样 ${m.samples} 帧 · 绘制 ${m.draw} ms · P95 帧间隔 ${m.p95} ms`;if($('#live-performance'))$('#live-performance').textContent=`画面已暂停 · 最近 ${m.fps} FPS · 绘制 ${m.draw} ms · P95 ${m.p95} ms`; }requestAnimationFrame(loop);
}
resize();requestAnimationFrame(loop);
